const unsetVariantDefault = `-- name: UnsetVariantDefault :many
UPDATE manufacturing.boms
SET is_default = false, revision = revision + 1, updated_at = $1::timestamptz
WHERE variant_id = $2 AND is_default AND id <> $3
RETURNING id
`

type UnsetVariantDefaultParams struct {
	Now       time.Time
	VariantID int32
	ExceptID  int64
}

// UnsetVariantDefault unmarks the variant's default BoM, but for except_id,
// moving its revision on, and answers the ids it unmarked.
func (q *Queries) UnsetVariantDefault(ctx context.Context, arg UnsetVariantDefaultParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, unsetVariantDefault, arg.Now, arg.VariantID, arg.ExceptID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

