const variantHasActiveDefault = `-- name: VariantHasActiveDefault :one
SELECT EXISTS (SELECT 1 FROM manufacturing.boms
               WHERE variant_id = $1 AND is_default AND status = 'active' AND id <> $2)
`

type VariantHasActiveDefaultParams struct {
	VariantID int32
	ExceptID  int64
}

// VariantHasActiveDefault reports whether the variant has an active default
// BoM other than except_id.
func (q *Queries) VariantHasActiveDefault(ctx context.Context, arg VariantHasActiveDefaultParams) (bool, error) {
	row := q.db.QueryRow(ctx, variantHasActiveDefault, arg.VariantID, arg.ExceptID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const variantsWithActiveBom = `-- name: VariantsWithActiveBom :many
SELECT DISTINCT variant_id FROM manufacturing.boms
WHERE variant_id = ANY($1::int[]) AND status = 'active'
ORDER BY variant_id
`

// VariantsWithActiveBom is which of variant_ids have at least one active
// BoM, for the variant search's hasBom.
func (q *Queries) VariantsWithActiveBom(ctx context.Context, variantIds []int32) ([]int32, error) {
	rows, err := q.db.Query(ctx, variantsWithActiveBom, variantIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int32
	for rows.Next() {
		var variant_id int32
		if err := rows.Scan(&variant_id); err != nil {
			return nil, err
		}
		items = append(items, variant_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
